from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(8))  # D0..D7
    units = list(range(8))  # U0..U7
    supplies = list(range(1))  # S0..S0
    days = list(range(4))  # Day0..Day3

    demands = [[[26.95, 39.06, 22.44, 23.09]], [[11.95, 46.61, 12.83, 20.64]], [[39.51, 25.46, 44.51, 31.24]], [[11.86, 14.03, 46.21, 29.13]], [[33.59, 28.76, 22.52, 44.8]], [[27.25, 39.47, 34.13, 17.34]], [[29.12, 33.18, 21.18, 37.5]], [[17.1, 32.08, 47.99, 47.91]]]
    depot_supplies = [[[24.1, 27.01, 31.42, 38.3]], [[30.71, 34.03, 40.4, 30.73]], [[30.78, 43.94, 35.32, 33.79]], [[25.59, 43.44, 46.01, 40.28]], [[25.54, 43.77, 37.08, 41.39]], [[28.19, 37.23, 28.45, 39.11]], [[31.55, 35.63, 27.07, 34.78]], [[31.47, 47.4, 45.53, 36.12]]]
    transport_costs = [[4.15, 3.86, 4.15, 3.49, 1.07, 2.72, 3.14, 2.43], [1.82, 2.54, 3.3, 2.47, 2.4, 1.31, 3.83, 1.17], [3.09, 3.97, 3.24, 2.19, 4.34, 1.69, 2.27, 4.35], [2.27, 3.42, 2.68, 3.75, 1.35, 4.14, 1.04, 2.14], [4.04, 4.07, 2.44, 1.52, 1.51, 1.66, 4.39, 2.51], [2.63, 3.62, 4.92, 4.51, 3.53, 2.56, 3.49, 4.38], [3.98, 4.58, 3.15, 2.18, 2.3, 2.98, 2.57, 1.02], [1.71, 1.04, 2.74, 3.16, 3.39, 3.01, 4.58, 2.28]]
    risk_costs = [[105.67, 104.12, 62.71, 114.25, 108.16, 111.37, 197.89, 82.11], [159.46, 59.09, 52.93, 131.42, 186.96, 138.12, 60.83, 138.84], [52.54, 175.1, 67.83, 127.86, 163.64, 157.87, 122.11, 59.63], [81.26, 69.86, 113.06, 130.49, 58.19, 139.43, 139.93, 93.66], [157.26, 161.04, 153.47, 148.72, 168.89, 107.56, 84.6, 114.75], [172.6, 135.19, 136.0, 124.0, 130.44, 125.9, 178.68, 146.56], [167.02, 186.5, 54.31, 160.47, 182.93, 139.19, 111.7, 113.46], [165.53, 191.18, 56.61, 187.29, 193.09, 141.51, 118.49, 52.06]]
    supply_volumes = [1.77]
    penalty_costs = [75.45]
    vehicle_cost = 10.0
    vehicle_capacity = 83.0
    total_vehicles = 11

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
